  const bad = () => { throw new SyntaxError() }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+') || peekOp('-')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp('*') || peekOp('/')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) { const op = toks[p++].v; return { type: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) bad()
    if (t.t === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!peekOp(')')) bad()
      p++
      return { type: 'paren', e }
    }
    if (t.t === 'word') {
      p++
      if (peekOp('(')) {
        p++
        const args = []
        if (peekOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (peekOp(',')) { p++; continue }
            if (peekOp(')')) { p++; break }
            bad()
          }
        }
        return { type: 'call', name: t.v.toUpperCase(), args }
      }
      const up = t.v.toUpperCase()
      if (peekOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.t !== 'word' || (toks[p + 1] && toks[p + 1].t === 'op' && toks[p + 1].v === '(')) bad()
        p++
        return { type: 'range', a: up, b: t2.v.toUpperCase() }
      }
      if (up === 'TRUE') return { type: 'bool', v: true }
      if (up === 'FALSE') return { type: 'bool', v: false }
      return { type: 'ref', w: up }
    }
    bad()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e instanceof SyntaxError) return null
    throw e
  }
}

function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push({ col: c, row: r })
  return out
}

function misplaced(n, isArg = false) {
  switch (n.type) {
    case 'range': return !isArg
    case 'bin': return misplaced(n.l) || misplaced(n.r)
    case 'un': return misplaced(n.e)
    case 'paren': return misplaced(n.e)
    case 'call': return n.args.some((x) => misplaced(x, true))
    default: return false
  }
}

function collectDeps(n, set) {
  switch (n.type) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.set(key(a), a); break }
    case 'range': { const cs = rangeCells(n); if (cs) for (const a of cs) set.set(key(a), a); break }
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'un': case 'paren': collectDeps(n.e, set); break
    case 'call': n.args.forEach((x) => collectDeps(x, set)); break
  }
}

// ---- evaluation
const parsed = new Map()
function getParsed(k) {
  if (!parsed.has(k)) {
    const c = cells.get(k)
    parsed.set(k, c.content[0] === '=' ? parseFormula(c.content.slice(1)) : undefined)
  }
  return parsed.get(k)
}

function literal(content) {
  if (content === '') return 0
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return Number(content)
  if (ERR_TOKENS.has(content)) return E(content)
  return new Text(content)
}

const memo = new Map()
const inProgress = new Set()
function cellValue(a) {
  const k = key(a)
  if (!cells.has(k)) return 0
  if (memo.has(k)) return memo.get(k)
  if (inProgress.has(k)) return E('#CYCLE!')
  const c = cells.get(k)
  let v
  if (c.content[0] !== '=') v = literal(c.content)
  else {
    const ast = getParsed(k)
    if (!ast || misplaced(ast)) v = E('#ERR!')
    else {
      inProgress.add(k)
      v = evalNode(ast)
      inProgress.delete(k)
    }
  }
  memo.set(k, v)
  return v
}

function num(v) {
  if (v instanceof Err) return v
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return E('#VALUE!')
}
const fin = (x) => (Number.isFinite(x) ? x : E('#DIV/0!'))
const kind = (v) => (typeof v === 'number' ? 0 : v instanceof Text ? 1 : 2)
function cpCmp(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  const ka = kind(a), kb = kind(b)
  if (ka !== kb) return ka - kb
  if (ka === 0) return a < b ? -1 : a > b ? 1 : 0
  if (ka === 1) return Math.sign(cpCmp(a.s, b.s))
  return (a ? 1 : 0) - (b ? 1 : 0)
}

function argValues(n) {
  if (n.type === 'range') {
    const cs = rangeCells(n)
    if (!cs) return [E('#REF!')]
    return cs.map(cellValue)
  }
  return [evalNode(n)]
}

function evalNode(n) {
  switch (n.type) {
    case 'num': return n.v
    case 'bool': return n.v
    case 'paren': return evalNode(n.e)
    case 'ref': { const a = parseAddr(n.w); return a ? cellValue(a) : E('#REF!') }
    case 'range': return E('#ERR!')
    case 'un': {
      const v = num(evalNode(n.e))
      if (v instanceof Err) return v
      return n.op === '-' ? -v : v
    }
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (l instanceof Err) return l
      if (r instanceof Err) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        switch (n.op) {
          case '=': return c === 0
          case '<>': return c !== 0
          case '<': return c < 0
          case '<=': return c <= 0
          case '>': return c > 0
          default: return c >= 0
        }
      }
      const x = num(l)
      if (x instanceof Err) return x
      const y = num(r)
      if (y instanceof Err) return y
      switch (n.op) {
        case '+': return fin(x + y)
        case '-': return fin(x - y)
        case '*': return fin(x * y)
        case '/': return y === 0 ? E('#DIV/0!') : fin(x / y)
        default: return fin(Math.pow(x, y))
      }
    }
    case 'call': return evalCall(n)
  }
}

function single(arg) {
  const vs = argValues(arg)
  return vs.length === 1 ? vs[0] : E('#ERR!')
}

function evalCall(n) {
  const { name, args } = n
  if (name === 'IF') {
    if (args.length !== 3) return E('#ERR!')
    const c = single(args[0])
    if (c instanceof Err) return c
    let t
    if (typeof c === 'boolean') t = c
    else if (typeof c === 'number') t = c !== 0
    else return E('#VALUE!')
    return single(args[t ? 1 : 2])
  }
  if (name === 'ABS') {
    if (args.length !== 1) return E('#ERR!')
    const v = single(args[0])
    const x = num(v)
    return x instanceof Err ? x : Math.abs(x)
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return E('#NAME?')
  if (args.length < 1) return E('#ERR!')
  const vals = args.flatMap(argValues)
  const e = vals.find((v) => v instanceof Err)
  if (e) return e
  if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
  const nums = []
  for (const v of vals) {
    const x = num(v)
    if (x instanceof Err) return x
    nums.push(x)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return Math.min(...nums)
    case 'MAX': return Math.max(...nums)
    default: return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

function show(v) {
  if (v instanceof Err) return v.t
  if (v instanceof Text) return v.s
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  return String(Number(v.toPrecision(10)))
}

const sorted = [...cells.values()].sort((a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row)
let out = ''
for (const c of sorted) {
  const k = key(c.addr)
  if (mode === 'values') out += `${k}=${show(cellValue(c.addr))}\n`
  else {
    const set = new Map()
    const ast = c.content[0] === '=' ? getParsed(k) : null
    if (ast) collectDeps(ast, set)
    const ds = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${k}:${ds.map((d) => ' ' + key(d)).join('')}\n`
  }
}
process.stdout.write(out)
